def can_vote(age, citizen):
    if not citizen:
        return False     # leave early, no else needed
    return age >= 18

def line(name, qty):
    return f"{name:<8}{qty:>3}"

def receipt(items):
    for name, qty in items:
        print(line(name, qty))

stock = {"potion": 3, "arrow": 20}
stock["potion"]              # 3
stock.get("shield", 0)       # 0 instead of KeyError
stock["arrow"] -= 5
for item, count in stock.items():
    print(item, count)

for i, name in enumerate(["Pixel", "Byte"], start=1):
    print(f"{i}. {name}")        # 1. Pixel / 2. Byte

for name, price in zip(["rope", "lamp"], [3, 12]):
    print(name, price)           # rope 3 / lamp 12

n, steps = 20, 0
while n > 1:
    n //= 2
    steps += 1              # 4 steps: 10, 5, 2, 1

for x in [3, -1, 4]:
    if x < 0:
        continue            # skip this item
    if x > 3:
        break               # leave the loop entirely

for name in crew:
    if name not in allowed:
        break
else:
    print("everyone is allowed")   # only if no break happened

label = "even" if n % 2 == 0 else "odd"

names = ["a", "b", "c"]
for i in range(len(names)):
    for j in range(i + 1, len(names)):
        print(names[i], names[j])  # a b, a c, b c

scores = [61, 48, 75]
[s * 2 for s in scores]             # [122, 96, 150]
[s for s in scores if s >= 50]      # [61, 75]
{s: s >= 50 for s in scores}        # {61: True, 48: False, 75: True}
{s // 10 for s in scores}           # {4, 6, 7}

def parse_price(text):
    try:
        return float(text)
    except ValueError:
        return None          # "n/a" -> None instead of a crash

try:
    value = risky()
except KeyError as err:
    log(f"missing {err}")
else:
    use(value)               # only when nothing was raised
finally:
    cleanup()                # always, even after a return

def withdraw(balance, amount):
    if amount <= 0:
        raise ValueError("amount must be positive")
    return balance - amount

