def top_shorts(videos, min_views):
    shorts = []
    for v in videos:
        if v["seconds"] <= 60:
            if v["views"] >= min_views:
                shorts.append(v)
    shorts.sort(key=lambda v: v["views"], reverse=True)
    titles = []
    for v in shorts:
        titles.append(v["title"])
    return titles

