    parts = [part.strip() for part in line.split(",")]
    if len(parts) != 3:
        raise ValueError("expected 3 fields")
    symbol, qty_text, side = parts
    try:
        qty = float(qty_text)
    except ValueError:
        raise ValueError("qty is not a number")
    return symbol.upper(), qty, side.lower()

